          "minItems": 0
        },
        "source_id": {
          "type": "string",
          "minLength": 1,
          "pattern": "^(?=.*\\S)[^\\x00-\\x1f\\x7f-\\x9f\\ud800-\\udfff]+(?![\\s\\S])"
        },
        "evidence": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/evidence"
          },
          "minItems": 1
        },
        "source_document": {
          "$ref": "#/$defs/source_document"
        },
        "scope_note": {
          "type": "string",
          "minLength": 1,
          "pattern": "^(?=.*\\S)[^\\x00-\\x1f\\x7f-\\x9f\\ud800-\\udfff]+(?![\\s\\S])"
        },
        "evaluation_support": {
          "const": "catalog_only"
        },
        "universal_bound": {
          "const": false
        },
        "engineering_allowable": {
          "const": false
        },
        "verification": {
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "source_inspection_scope": {
              "type": "string",
              "minLength": 1,
              "pattern": "^(?=.*\\S)[^\\x00-\\x1f\\x7f-\\x9f\\ud800-\\udfff]+(?![\\s\\S])"
            },
            "transcription_cross_check": {
              "const": "completed"
            },
            "independent_scientific_review": {
              "const": false
            },
            "raw_data_reanalysis": {
              "const": false
            }
          },
          "required": [
            "source_inspection_scope",
            "transcription_cross_check",
            "independent_scientific_review",
            "raw_data_reanalysis"
          ]
        },
        "derivation": {
          "$ref": "#/$defs/derivation"
        }
      },
      "required": [
        "id",
        "version",
        "material_state_id",
        "quantity",
        "quantity_dimension",
        "source_property_label",
        "reported_value",
        "evidence_kind",
        "reporting_basis",
        "determination_basis",
        "basis_note",
        "conditions",
        "density_basis",
        "summary_statistic",
        "uncertainty",
        "uncertainty_status",
        "uncertainty_note",
        "sample_count",
        "method_definition",
        "source_discrepancies",
        "source_id",
        "evidence",
        "source_document",
        "scope_note",
        "evaluation_support",
        "universal_bound",
        "engineering_allowable",
        "verification"
      ]
    }
  }
}
